import json,statistics,math
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=Path('results/mnist_short_term_context_20261105');rs=json.loads((p/'results.json').read_text());selection=json.loads((p/'selection.json').read_text());summary=[]
def stats(stream,policy,intervention,key='accuracy'):
 rows=[r for r in rs if r['stream']==stream and r['policy']==policy and r['intervention']==intervention];v=[statistics.mean(r['score'][key]*100 for r in rows if r['seed']==s) for s in [101,102,103]];return statistics.mean(v),statistics.stdev(v)
lines=['# Short-term branch state: causal frozen-network evaluation','', 'Exploratory inference-only test on six frozen sparse-MNIST MLP checkpoints (three seeds × two training orders). All 10,000 official test images appear once per stream. Models remain frozen. This evaluates inference-state context retention and switch recovery, not training-time weight forgetting.','', '| State policy | Intervention | Persistent context accuracy | Random mixed accuracy |','|---|---|---:|---:|']
for policy in ['none','magnitude','pseudo','supervised']:
 for intervention in (['retain'] if policy=='none' else ['retain','reset_each','shuffle_branches']):
  v=[]
  for stream in ['blocked','mixed']:
   mean,sd=stats(stream,policy,intervention);summary.append(dict(stream=stream,policy=policy,intervention=intervention,accuracy=mean,seed_sd=sd));v.append(f'{mean:.2f} ± {sd:.2f}%')
  lines.append(f'| {policy} | {intervention} | '+' | '.join(v)+' |')
lines+=['','## Selected state parameters','']
for policy,conf in selection.items():lines.append(f"- {policy}: decay={conf['decay']}, state strength={conf['strength']}; validation persistent-context accuracy={100*conf['validation_accuracy']:.2f}%.")
lines+=['','## Adaptation after context switches','', '| Policy, state retained | First 20 queries after switch | Queries 101–200 after switch | Mean gate overlap between contexts |','|---|---:|---:|---:|']
for policy in ['none','magnitude','pseudo','supervised']:
 rows=[r for r in rs if r['stream']=='blocked' and r['policy']==policy and r['intervention']=='retain'];early=statistics.mean(r['score']['early_after_switch'] for r in rows)*100;late=statistics.mean(r['score']['late_after_switch'] for r in rows)*100;overlap=statistics.mean(r['score']['context_gate_overlap'] for r in rows);lines.append(f'| {policy} | {early:.2f}% | {late:.2f}% | {overlap:.3f} |')
rows=[r for r in rs if r['stream']=='blocked' and r['policy']=='pseudo' and r['intervention']=='retain'];diff=[]
for seed in [101,102,103]:
 d=[]
 for r in [r for r in rows if r['seed']==seed]:
  b=next(b for b in rs if b['stream']=='blocked' and b['policy']=='none' and b['seed']==seed and b['first']==r['first']);d.append((r['score']['accuracy']-b['score']['accuracy'])*100)
 diff.append(statistics.mean(d))
mean=statistics.mean(diff);half=4.30265273*statistics.stdev(diff)/math.sqrt(3)
lines+=['',f'Pseudo-error state paired gain in persistent streams: **{mean:+.2f} pp**, descriptive seed-level 95% t interval [{mean-half:+.2f}, {mean+half:+.2f}] pp.','', '## How it works','', 'Current-image baseline produces magnitude-soft branch weights and a ten-class prediction. For each neuron, replace only that neuron’s mixture with each branch and measure cross entropy against the baseline’s own predicted class (not the true label). Center and scale the four errors within that neuron, then softmax the negative standardized errors to obtain branch preferences. EMA stores these preferences after prediction. On the next image, combine its current-image weights with the previous EMA: gate = .1 current + .9 state for the selected pseudo policy. No task boundary, task ID, prototype, query label or stored example enters this label-free state. Fixed stateless probes define update preferences; probes are not recomputed under the current state.', '', 'Magnitude state instead averages recent magnitude-soft branch weights. Supervised control uses true-label counterfactual errors after each prediction: its accuracy is not label-free. It is a matched feedback control, not the exact original training error-trace algorithm, because it stores standardized branch preferences.', '', 'Persistent stream rotates 200-image blocks from each digit pair; context recurs. Mixed stream randomly permutes the same images. Labels construct benchmark order and score predictions but are not provided to label-free state. Retain keeps the causal state. Reset_each removes it before every prediction, recovering the stateless baseline exactly. Shuffle_branches independently permutes each neuron’s historical branch assignments before use while maintaining the unshuffled underlying EMA update.', '', 'State has 168×4 float32 values: **2,688 bytes**. It requires no new trainable parameters and stores no examples. Counterfactual probes add compute, not included in the state-memory count. Core model remains 134,074 parameters and about 1.593 MB of persistent tensors. Implementation precomputes independent per-image probes for experimental efficiency; streaming deployment can compute each probe on arrival. The algorithm only reads the current probe and previous state.','', '## Limits','', '- All checkpoints were trained with supervised error-trace selection and the auxiliary loss. This is not a comparison of networks trained without traces versus label-free traces. It isolates the additional inference-time state mechanism.','- No new training/weight-forgetting experiment was conducted. Early-versus-late switch accuracy measures adaptation, not changes in long-term weights. Context gate overlap is mean histogram intersection (1 means identical average gates), not proof of isolated subnetworks.','- State parameters were selected on the original validation split for persistent streams. Mixed-stream scores use those same parameters without retuning. The beneficial setting exploits temporal context persistence; random mixing is a failure case, not something hidden by the summary.','- Pseudo-labels can be wrong, and this does not establish correctness of the inferred context or novel-class learning. Three seeds and one stream construction per checkpoint leave uncertainty; alternative context durations and datasets remain untested.','- Accuracy ± SD averages the two orders within each of three seeds. Repeated streams share query images. Stateless accuracy rounds to 66.70%, matching the earlier image-only result; comparisons use the matched scoring implementation.','- Three tests passed: state reset equals stateless predictions, label-free policies ignore supervised feedback arrays, and each stream contains every image exactly once. All original model tensors were checked unchanged.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n');(p/'summary.json').write_text(json.dumps(summary,indent=2))
fig,axs=plt.subplots(1,2,figsize=(12,4.8));colors={'none':'#64748b','magnitude':'#0891b2','pseudo':'#7c3aed','supervised':'#d97706'};labels={'none':'No state','magnitude':'Response state','pseudo':'Pseudo-error state (label-free)','supervised':'True-label feedback control'}
for policy in colors:
 values=[stats(stream,policy,'retain') for stream in ['blocked','mixed']];axs[0].errorbar([0,1],[v[0] for v in values],yerr=[v[1] for v in values],marker='o',capsize=3,color=colors[policy],label=labels[policy]);rows=[r for r in rs if r['stream']=='blocked' and r['policy']==policy and r['intervention']=='retain'];curve=[100*statistics.mean(r['score']['switch_curve'][i] for r in rows) for i in range(10)];axs[1].plot([10+20*i for i in range(10)],curve,marker='.',color=colors[policy])
axs[0].set_xticks([0,1],['200-image contexts','Randomly mixed']);axs[0].set_ylabel('Test accuracy (%)');axs[0].set_ylim(35,102);axs[0].set_title('State helps only when context persists')
axs[1].set_xlabel('Images since context switch (20-image bins)');axs[1].set_ylabel('Accuracy (%)');axs[1].set_ylim(35,102);axs[1].set_title('Recovery after context switches')
for ax in axs:ax.grid(alpha=.2)
handles,labs=axs[0].get_legend_handles_labels();fig.legend(handles,labs,loc='lower center',ncol=2,fontsize=9);fig.suptitle('Short-term branch state on a frozen sparse MLP');fig.tight_layout(rect=(0,.15,1,.94));fig.savefig(p/'short_term_context.png',dpi=180);plt.close(fig)
print('\n'.join(lines[:30]));print('paired gain',mean,'interval',mean-half,mean+half)
